/** Explicitly fictional complete actual source records; no production facts/defaults. */
import {guidedPARoyaltyComplete,rawGuidedPARoyaltyCohort} from './guided-pa-royalty-complete';
import type {GuidedPAOrdinaryReturnCompletionSources} from '@/lib/guided-pa-ordinary-return-completion';
export const currentMIWorkspaceId='native-current-return-2025';
export const historicalMIWorkspaceId='independently-entered-filed-return-2025';
export function nativeMIRoyaltyFixture(corrected=false){
 const f=guidedPARoyaltyComplete('browser',corrected);
 const completion:GuidedPAOrdinaryReturnCompletionSources=structuredClone(f.completion);
 Reflect.deleteProperty(completion.otherStateTaxes,'refundedRoyaltySources');completion.sourceFactsConfirmed=null;
 return {...f,completionWithoutMI:completion,historicalState:rawGuidedPARoyaltyCohort('browser'),currentWorkspaceId:currentMIWorkspaceId,historicalWorkspaceId:historicalMIWorkspaceId};
}
/** Plain native label/value entry contract, wholly separate from product field tables. */
export function nativeMIAgencyEntries(f:ReturnType<typeof nativeMIRoyaltyFixture>):Array<[string,string]>{
 const p=f.refund,row=p.statements[0];if(!row)throw Error('Complete fictional MI statement required');
 const entries:Array<[string,string]>=[['MI refund source tax year','2025'],['MI refund original source reference',p.sourceReference],['MI refund complete through date',p.completeThroughDate],['MI refund packet actual owner','primary'],['All actual MI income tax originals reviewed','true'],['No other MI income credits payments or assessments','true'],['MI withholding original 1 actual entered royalty statement','0'],['MI withholding original 1 source reference',row.sourceReference],['MI withholding original 1 all original source facts reviewed','true']];
 const identity=(label:string,x:{sourceTaxYear:number|null;state:string;sourceReference:string})=>entries.push([label+' actual tax year',String(x.sourceTaxYear)],[label+' actual owner','primary'],[label+' actual state',x.state],[label+' original source reference',x.sourceReference]);
 identity('MI remittance 1',row.withholdingOriginal);
 for(const [key,label]of[['date','actual payment date'],['amount','actual amount'],['confirmationNumber','actual confirmation number'],['actuallyRemittedConfirmed','actually remitted']]as const)entries.push(['MI remittance 1 '+label,String(row.withholdingOriginal[key])]);
 for(const [key,label]of[['sourceReference','original source reference'],['propertyId','actual property identifier'],['publisherName','actual publisher'],['publicationOriginState','actual publication origin state'],['publicationFrom','actual publication from'],['publicationThrough','actual publication through'],['ownerCommercialDomicileState','actual commercial domicile'],['michiganSourceGross','actual MI gross'],['outsideMichiganGross','actual outside MI gross'],['allPublicationUsesReviewedConfirmed','all publication uses reviewed'],['actualPublicationOriginConfirmed','actual publication origin checked'],['nonbusinessCopyrightConfirmed','actual nonbusiness copyright']]as const)entries.push(['MI copyright use 1 '+label,String(row.copyrightUse[key])]);
 identity('MI filed return',p.filedReturn);
 for(const [key,label]of[['returnId','actual return identifier'],['returnKind','actual return kind'],['filingStatus','actual filing status'],['residency','actual residency'],['filedOn','actual filed date'],['completeReturnScheduleWAndNRConfirmed','complete return W and NR checked'],['allIncomeAndAdjustmentsReviewedConfirmed','all income and adjustments reviewed'],['finalTax','actual final tax'],['reportedWithholding','actual reported withholding'],['totalPayments','actual total payments'],['overpayment','actual overpayment'],['refundRequested','actual requested refund'],['michiganSourceIncome','actual MI source income'],['noOtherPaymentsCreditsOffsetsOrTransfersConfirmed','no other payments credits offsets or transfers']]as const)entries.push(['MI filed return '+label,String(p.filedReturn[key])]);
 identity('MI written claim',p.writtenClaim);
 for(const [key,label]of[['applicationId','actual application identifier'],['submittedOn','actual submitted date'],['amountRequested','actual requested amount'],['fullOriginalPaymentDemandConfirmed','full original payment demanded'],['actuallySubmittedConfirmed','actually submitted']]as const)entries.push(['MI written claim '+label,String(p.writtenClaim[key])]);
 identity('MI agency award',p.agencyAward);
 for(const [key,label]of[['awardId','actual award identifier'],['issuedOn','actual issued date'],['applicationId','actual linked application identifier'],['originalReportedStateIncome','actual original reported state income'],['determinedMichiganSourceIncome','actual determined MI source income'],['determinationReason','actual determination reason'],['finalTaxDetermined','actual final tax determined'],['refundAwarded','actual refund awarded'],['printedReturnToExactAwardReconciledConfirmed','printed return and exact award reconciled'],['actualAgencyDeterminationConfirmed','actual determination checked']]as const)entries.push(['MI agency award '+label,String(p.agencyAward[key])]);
 identity('MI received refund',p.refund);
 for(const [key,label]of[['postedOn','actual posted date'],['receivedOn','actual received date'],['amount','actual received amount'],['confirmationNumber','actual confirmation number'],['actuallyReceivedConfirmed','actually received']]as const)entries.push(['MI received refund '+label,String(p.refund[key])]);
 identity('MI complete account',p.account);
 for(const [key,label]of[['completeThroughDate','actual complete through date'],['allPaymentsRefundsTransfersOffsetsAndAdjustmentsReviewedConfirmed','all payments refunds transfers offsets and adjustments reviewed'],['noAmendmentAssessmentOrPendingAdjustmentConfirmed','no amendment assessment or pending adjustment'],['netTaxPaymentsReported','actual net tax payments'],['unpaidTaxReported','actual unpaid tax'],['overpaymentOutstandingReported','actual outstanding overpayment']]as const)entries.push(['MI complete account '+label,String(p.account[key])]);
 return entries;
}

/** All actual historical correction rows have structured labels; never a JSON/object editor. */
export function nativeMICorrectionEntries(f:ReturnType<typeof nativeMIRoyaltyFixture>):Array<[string,string]>{
 const c=f.historicalExpenseCorrection,entries:Array<[string,string]>=[];
 for(const[key,label]of[['sourceTaxYear','actual tax year'],['sourceReference','original source reference'],['reviewedOn','actual reviewed date'],['returnId','actual return identifier'],['originalFiledFederalAGI','actual originally filed federal AGI'],['currentFederalAGI','actual current federal AGI'],['actualAdditionalExpense','actual additional paid expense'],['allOriginalAndCorrectedIncomeExpensesAndUsesReviewedConfirmed','all original corrected income expenses and uses reviewed'],['michiganTaxableIncomeEffect','actual MI taxable income effect'],['michiganTaxEffect','actual MI tax effect']]as const)entries.push(['MI expense correction '+label,String(c[key])]);
 entries.push(['MI expense correction actual owner','primary']);
 for(const[label,receipt]of[['Original legal receipt',c.originalLegalReceipt],['Corrected legal receipt',c.correctedLegalReceipt]]as const){
  for(const[key,title]of[['sourceId','actual source identifier'],['sourceReference','original source reference'],['paidDate','actual paid date'],['amountPaid','actual paid amount'],['category','actual category'],['ordinaryNecessaryForProperty','ordinary and necessary for property'],['relatesOnlyToCurrentYear','relates only to current year'],['capitalOrImprovement','capital or improvement'],['personalOrOwnLabor','personal or own labor'],['reimbursed','reimbursed']]as const)entries.push([label+' '+title,String(receipt[key])]);
 }
 for(const[label,use]of[['Original correction copyright use',c.originalCopyrightUse],['Current correction copyright use',c.currentCopyrightUse]]as const){
  for(const[key,title]of[['sourceReference','original source reference'],['propertyId','actual property identifier'],['publisherName','actual publisher'],['publicationOriginState','actual publication origin state'],['publicationFrom','actual publication from'],['publicationThrough','actual publication through'],['ownerCommercialDomicileState','actual commercial domicile'],['michiganSourceGross','actual MI gross'],['outsideMichiganGross','actual outside MI gross'],['allPublicationUsesReviewedConfirmed','all publication uses reviewed'],['actualPublicationOriginConfirmed','actual publication origin checked'],['nonbusinessCopyrightConfirmed','actual nonbusiness copyright']]as const)entries.push([label+' '+title,String(use[key])]);
 }
 for(const[key,title]of[['sourceReference','original source reference'],['reviewedOn','actual reviewed date'],['allFederalAndMichiganAdjustmentsReviewedConfirmed','all federal and MI adjustments reviewed'],['determination','actual determination'],['noMichiganAmendmentRequiredConfirmed','actual no MI amendment required determination']]as const)entries.push(['Actual amendment review '+title,String(c.amendmentReview[key])]);
 const a=c.completeAccountAfterReview;entries.push(['Post-review MI account actual tax year','2025'],['Post-review MI account actual owner','primary'],['Post-review MI account actual state',a.state]);
 for(const[key,title]of[['sourceReference','original source reference'],['completeThroughDate','actual complete through date'],['allPaymentsRefundsTransfersOffsetsAndAdjustmentsReviewedConfirmed','all payments refunds transfers offsets and adjustments reviewed'],['noAmendmentAssessmentOrPendingAdjustmentConfirmed','no amendment assessment or pending adjustment'],['netTaxPaymentsReported','actual net tax payments'],['unpaidTaxReported','actual unpaid tax'],['overpaymentOutstandingReported','actual outstanding overpayment']]as const)entries.push(['Post-review MI account '+title,String(a[key])]);
 return entries;
}

/** Separately entered actual FILED use. Never copied from current use by product code. */
export function nativeMIFiledUseEntries(f:ReturnType<typeof nativeMIRoyaltyFixture>):Array<[string,string]>{
 const use=f.filedFederalHistory.originalCopyrightUse;
 return([['sourceReference','original source reference'],['propertyId','actual property identifier'],['publisherName','actual publisher'],['publicationOriginState','actual publication origin state'],['publicationFrom','actual publication from'],['publicationThrough','actual publication through'],['ownerCommercialDomicileState','actual commercial domicile'],['michiganSourceGross','actual MI gross'],['outsideMichiganGross','actual outside MI gross'],['allPublicationUsesReviewedConfirmed','all publication uses reviewed'],['actualPublicationOriginConfirmed','actual publication origin checked'],['nonbusinessCopyrightConfirmed','actual nonbusiness copyright']]as const).map(([key,label])=>['Filed copyright use '+label,String(use[key])]);
}
